/**
 * Typed access to the success-rate results the site shows, as three result
 * sets (src/lib/release.ts):
 *
 *   paper-validation    v1.0.0, the results presented in the paper: twelve
 *                       models under five harnesses on 396 validation tasks,
 *                       three runs. Generated by scripts/export_paper.py,
 *                       which checks all 300 cells against the figure printed
 *                       in the paper.
 *   validation, test    v1.1.0, the baselines of the paper's section on the
 *                       later release: twelve models under the bare harness
 *                       on 400 tasks per split, one scored trajectory per
 *                       model and task. Generated by
 *                       scripts/export_leaderboard.py from the result exports.
 *                       The validation set also holds the submitted entries
 *                       (submissions/): scripts/build_board.py adds them to
 *                       the baselines when the site is built. A submitted
 *                       entry is a model under a harness, so in this set a
 *                       model need not have a result under every harness.
 *
 * A component takes the selected set with useResults() and reads everything
 * from it, so the same table, gap summary, and chart draw all three.
 *
 * Use `cell.meanText` / `cell.sdText` to show a value: they are the exact
 * one-decimal strings the paper prints. Use `formatRate` / `formatDelta` for
 * numbers derived here (group means, gaps). Differences are always computed
 * from unrounded means, as in the paper.
 */
import paperData from '../data/paper/leaderboard.json';
import releaseData from '../data/leaderboard.v1.1.0.json';
import validationBoard from '../data/leaderboard.v1.1.0.validation.json';
import type { RunDetails } from '../types/platform';
import { releaseOf, useResultSet, type Release, type ResultSet } from './release';

export type SettingId = 'Average' | 'ST' | 'IF' | 'MT' | 'MTIF';
export type TaskSettingId = Exclude<SettingId, 'Average'>;
export type HarnessId = 'bare' | 'hermes' | 'opencode' | 'openhands' | 'openclaw';
export type Access = 'closed' | 'open';

export interface Model {
  id: string;
  name: string;
  developer: string;
  /** closed = proprietary model; open = open-weight model. */
  access: Access;
  /** One of the three reference models used to select tasks during construction. */
  reference: boolean;
}
export interface Harness { id: HarnessId; name: string; abbr: string; kind: 'bare' | 'end-user' }
/**
 * The two views over all harnesses of a result set with several, offered
 * beside the harnesses: `average`, a model's success rate averaged over the
 * harnesses, and `best`, a model under whichever harness gives it the highest rate.
 */
export type AggregateId = 'average' | 'best';
/** What a row of results stands for: one harness, or one of the two views over all of them. */
export interface RowHarness { id: HarnessId | AggregateId; name: string; abbr: string; kind: 'bare' | 'end-user' | 'aggregate' }
export interface Setting { id: SettingId; name: string; description: string }
/**
 * Success rate in percent and its rank among the models in that column.
 * With several runs, `mean` is their mean and `sd` the standard deviation
 * across them; with one run there is no `sd`, and `passed` of `scored` tasks
 * are the counts behind the rate. In the `best` view each cell also names the
 * harness that gives the value (it can differ from one task setting to the next).
 */
export interface Cell {
  mean: number;
  sd: number | null;
  /** Absolute 95% task-bootstrap confidence limits, in percent. */
  ci95?: [number, number];
  rank: number;
  meanText: string;
  sdText: string | null;
  passed?: number;
  scored?: number;
  harness?: Harness;
}
/** What the site shows about a submitted entry besides its numbers (scripts/build_board.py). */
export interface Submission {
  /** The entry: `<model id>-<harness id>`. */
  id: string;
  submitter: string;
  submitterUrl?: string;
  modelUrl?: string;
  /** The day the entry was submitted, as YYYY-MM-DD. */
  submittedOn: string;
  /** Address of the archive with the trajectory and the verifier votes of every task. */
  trajectories: string;
  /** The score file in the site's repository. */
  scoreFile: string;
  /** Tasks that were run again after a scored result, as the submitter counted them; the newest result of a task counts. */
  rerunTasks: number;
}
export interface ResultRow {
  model: Model;
  harness: RowHarness;
  cells: Record<SettingId, Cell>;
  /** Who ran the evaluation, where the result set names it. */
  submitter?: string;
  /** Present on a submitted entry; a baseline has none. */
  submission?: Submission;
}

/** One harness, or one of the two views over all of them. */
export type HarnessScope = HarnessId | AggregateId;

/** One result set as the export scripts write it. */
interface ResultFile {
  runs: number;
  taskCounts: Record<string, number>;
  settings: Setting[];
  harnesses: Harness[];
  models: Model[];
  /** By task setting, model and harness. A model has cells under the harnesses it has results for. */
  results: Record<string, Record<string, Record<string, Cell>>>;
  /** The submitted entries, by model and harness. */
  entries?: Record<string, Record<string, Submission>>;
  /** Who ran the entries of the set that are not submitted ones: its baselines. */
  baselineSubmitter?: string;
  /** The settings each entry was run under, by model and harness. */
  runDetails?: Record<string, Record<string, RunDetails>>;
  /** Each model's rate averaged over the harnesses, computed per run by the export (not printed in the paper). */
  harnessAverage?: Record<string, Record<string, Omit<Cell, 'rank' | 'harness'>>>;
}

export const AGGREGATES: Record<AggregateId, RowHarness> = {
  average: { id: 'average', name: 'Average', abbr: 'Avg', kind: 'aggregate' },
  best: { id: 'best', name: 'Best', abbr: 'Best', kind: 'aggregate' },
};

/** The paper's terms for the two model groups. */
export const ACCESS_LABEL: Record<Access, string> = { closed: 'Proprietary', open: 'Open-weight' };
export const ACCESS_ORDER: Access[] = ['closed', 'open'];

export const isAggregate = (scope: HarnessScope): scope is AggregateId => scope === 'average' || scope === 'best';
export const rowKey = (row: ResultRow) => `${row.model.id}:${row.harness.id}`;

/** Round half up to one decimal, the same rule the exports use for the paper's printed values. */
export function formatRate(value: number): string {
  return (Math.sign(value) * Math.round(Math.abs(value) * 10) / 10).toFixed(1);
}

/** Signed one-decimal difference in percentage points, with a true minus sign. */
export function formatDelta(value: number): string {
  const text = formatRate(Math.abs(value));
  return text === '0.0' ? '0.0' : `${value < 0 ? '−' : '+'}${text}`;
}

/**
 * Rank of every row for one setting: 1 + the number of rows with a strictly
 * higher mean. For a single harness this equals the paper's within-column rank.
 */
export function ranksFor(rows: ResultRow[], setting: SettingId): Map<string, number> {
  return new Map(rows.map(row => [rowKey(row), 1 + rows.filter(other => other.cells[setting].mean > row.cells[setting].mean).length]));
}

/** Sort by one setting's mean. Ties keep the row order of the export, so the result is stable. */
export function sortRows(rows: ResultRow[], setting: SettingId, direction: 'desc' | 'asc' = 'desc'): ResultRow[] {
  const sign = direction === 'desc' ? -1 : 1;
  return rows.map((row, index) => ({ row, index }))
    .sort((a, b) => sign * (a.row.cells[setting].mean - b.row.cells[setting].mean) || a.index - b.index)
    .map(item => item.row);
}

export interface GroupStat {
  access: Access;
  /** Number of models in the group. */
  count: number;
  /** The group's best model for this harness and setting. */
  best: ResultRow;
  bestMean: number;
  /** Unweighted mean of the group's models. */
  mean: number;
}
export interface AccessGap {
  scope: HarnessScope;
  setting: Setting;
  /** Number of models compared. */
  entries: number;
  closed: GroupStat;
  open: GroupStat;
  /** Best proprietary mean minus best open-weight mean, in percentage points (unrounded). */
  bestGap: number;
  /** Proprietary group mean minus open-weight group mean, in percentage points (unrounded). */
  meanGap: number;
  /** Rank of the best open-weight entry among all entries in scope. */
  bestOpenRank: number;
}

function groupStat(rows: ResultRow[], access: Access, setting: SettingId): GroupStat {
  const group = rows.filter(row => row.model.access === access);
  const best = sortRows(group, setting)[0];
  const mean = group.reduce((sum, row) => sum + row.cells[setting].mean, 0) / group.length;
  return { access, count: group.length, best, bestMean: best.cells[setting].mean, mean };
}

/** One result set: its models, harnesses, and task settings, and every view the site draws from them. */
export class Results {
  readonly set: ResultSet;
  readonly release: Release;
  readonly models: Model[];
  readonly harnesses: Harness[];
  readonly settings: Setting[];
  readonly settingIds: SettingId[];
  readonly taskCounts: Record<TaskSettingId, number>;
  readonly totalTasks: number;
  readonly runs: number;
  /** The cells have a standard deviation across runs. With one run they have none. */
  readonly hasSpread: boolean;
  /** The harnesses, then the two views over all of them when there are several. */
  readonly scopes: HarnessScope[];
  private readonly cells: ResultFile['results'];
  private readonly entries: NonNullable<ResultFile['entries']>;
  private readonly baselineSubmitter: string | undefined;
  private readonly runDetails: NonNullable<ResultFile['runDetails']>;
  private readonly harnessAverage: ResultFile['harnessAverage'];

  constructor(set: ResultSet, file: ResultFile) {
    this.set = set;
    this.release = releaseOf(set);
    this.models = file.models;
    this.harnesses = file.harnesses;
    this.settings = file.settings;
    this.settingIds = file.settings.map(setting => setting.id);
    this.taskCounts = file.taskCounts as Record<TaskSettingId, number>;
    this.totalTasks = Object.values(file.taskCounts).reduce((sum, count) => sum + count, 0);
    this.runs = file.runs;
    this.cells = file.results;
    this.entries = file.entries ?? {};
    this.baselineSubmitter = file.baselineSubmitter;
    this.runDetails = file.runDetails ?? {};
    this.harnessAverage = file.harnessAverage;
    this.hasSpread = file.runs > 1;
    this.scopes = [...file.harnesses.map(harness => harness.id), ...(file.harnessAverage && file.harnesses.length > 1 ? ['average', 'best'] as const : [])];
  }

  /** The models ran under more than one harness. */
  get severalHarnesses(): boolean { return this.harnesses.length > 1; }
  /** A selection made on another result set, or the first harness when this set does not have it. */
  scopeOr(scope: HarnessScope): HarnessScope { return this.scopes.includes(scope) ? scope : this.harnesses[0].id; }

  harnessById(id: HarnessId): Harness { return this.harnesses.find(harness => harness.id === id)!; }
  settingById(id: SettingId): Setting { return this.settings.find(setting => setting.id === id)!; }
  cellFor(setting: SettingId, modelId: string, harness: HarnessId): Cell { return this.cells[setting][modelId][harness]; }
  /** Whether the model has results under the harness. Always true in a set where every model ran under every harness. */
  has(modelId: string, harness: HarnessId): boolean { return this.cells.Average[modelId]?.[harness] !== undefined; }
  /** The submission behind a model's results under a harness; undefined for a baseline. */
  submissionOf(modelId: string, harness: HarnessId): Submission | undefined { return this.entries[modelId]?.[harness]; }
  /** Who ran a model's evaluation under a harness: the submitter of a submitted entry, or the one of the baselines where the set names it. */
  submitterOf(modelId: string, harness: HarnessId): string | undefined { return this.submissionOf(modelId, harness)?.submitter ?? this.baselineSubmitter; }
  /** The settings a model was run under with a harness, where the set records them. */
  runDetailsOf(modelId: string, harness: HarnessId): RunDetails | undefined { return this.runDetails[modelId]?.[harness]; }
  /** The set names who ran its entries. */
  get hasSubmitters(): boolean { return this.baselineSubmitter !== undefined || Object.keys(this.entries).length > 0; }
  tasksFor(setting: SettingId): number { return setting === 'Average' ? this.totalTasks : this.taskCounts[setting]; }

  private rowFor(model: Model, harness: Harness): ResultRow {
    const cells = Object.fromEntries(this.settingIds.map(setting => [setting, this.cellFor(setting, model.id, harness.id)])) as Record<SettingId, Cell>;
    const submission = this.submissionOf(model.id, harness.id);
    const submitter = this.submitterOf(model.id, harness.id);
    return { model, harness, cells, ...(submitter ? { submitter } : {}), ...(submission ? { submission } : {}) };
  }

  /** The models with results under one harness, in the row order of the export. */
  rowsForHarness(harness: HarnessId): ResultRow[] {
    const selected = this.harnessById(harness);
    return this.models.filter(model => this.has(model.id, harness)).map(model => this.rowFor(model, selected));
  }

  /** Every model-harness pair with results. */
  allRows(): ResultRow[] {
    return this.harnesses.flatMap(harness => this.rowsForHarness(harness.id));
  }

  /** Ranks the models within every task setting: 1 + the number of models with a strictly higher mean. */
  private withRanks(rows: ResultRow[]): ResultRow[] {
    for (const setting of this.settingIds) {
      for (const row of rows) row.cells[setting].rank = 1 + rows.filter(other => other.cells[setting].mean > row.cells[setting].mean).length;
    }
    return rows;
  }

  /** Every model with its success rate averaged over the harnesses. */
  private averageRows(): ResultRow[] {
    const average = this.harnessAverage!;
    return this.withRanks(this.models.map(model => ({
      model,
      harness: AGGREGATES.average,
      cells: Object.fromEntries(this.settingIds.map(setting => [setting, { ...average[setting][model.id], rank: 0 }])) as Record<SettingId, Cell>,
    })));
  }

  /**
   * Every model under its best harness: per task setting, the harness with the
   * highest mean (the first in the harness order on a tie) and that pair's result.
   */
  private bestRows(): ResultRow[] {
    return this.withRanks(this.models.map(model => ({
      model,
      harness: AGGREGATES.best,
      cells: Object.fromEntries(this.settingIds.map(setting => {
        const harness = this.harnesses.reduce((best, candidate) => (this.cellFor(setting, model.id, candidate.id).mean > this.cellFor(setting, model.id, best.id).mean ? candidate : best));
        return [setting, { ...this.cellFor(setting, model.id, harness.id), rank: 0, harness }];
      })) as Record<SettingId, Cell>,
    })));
  }

  /** One row per model, for a harness or for a view over all of them. */
  rowsForScope(scope: HarnessScope): ResultRow[] {
    return scope === 'average' ? this.averageRows() : scope === 'best' ? this.bestRows() : this.rowsForHarness(scope);
  }

  /** In the `best` view, the model-harness pair behind a row's value for one task setting. */
  pairBehind(row: ResultRow, setting: SettingId): ResultRow {
    const harness = row.cells[setting].harness;
    return harness ? this.rowFor(row.model, harness) : row;
  }

  /**
   * Proprietary vs open-weight comparison for one setting: the models under one
   * harness, their averages over the harnesses, or each model under its best harness.
   */
  accessGap(scope: HarnessScope, setting: SettingId): AccessGap {
    const rows = this.rowsForScope(scope);
    const closed = groupStat(rows, 'closed', setting);
    const open = groupStat(rows, 'open', setting);
    return {
      scope,
      setting: this.settingById(setting),
      entries: rows.length,
      closed,
      open,
      bestGap: closed.bestMean - open.bestMean,
      meanGap: closed.mean - open.mean,
      bestOpenRank: ranksFor(rows, setting).get(rowKey(open.best))!,
    };
  }

  /** The best model-harness pair for a setting, optionally within one access group. */
  bestPair(setting: SettingId = 'Average', access?: Access): ResultRow {
    const rows = this.allRows().filter(row => !access || row.model.access === access);
    return sortRows(rows, setting)[0];
  }

  /**
   * All results as CSV text (one row per model and harness), for the download
   * button. With several runs each setting has its mean, standard deviation, and
   * rank; with one run, its rate, the passed and scored tasks, and rank.
   * Task-bootstrap CI limits, when available, are percentages in separate columns.
   */
  csv(): string {
    const rows = this.allRows();
    const withIntervals = rows.some(row => this.settingIds.some(setting => row.cells[setting].ci95));
    const columns = [
      ...(this.hasSpread ? ['mean', 'sd', 'rank'] : ['success_rate', 'passed', 'tasks', 'rank']),
      ...(withIntervals ? ['ci95_low', 'ci95_high'] : []),
    ];
    // A set that names who ran its entries has a column for it.
    const quoted = (text: string) => (/[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text);
    const header = ['model', 'developer', 'access', 'harness', ...(this.hasSubmitters ? ['submitted_by'] : []),
      ...this.settingIds.flatMap(setting => columns.map(column => `${setting}_${column}`))];
    const lines = rows.map(row => [
      quoted(row.model.name), quoted(row.model.developer), ACCESS_LABEL[row.model.access], row.harness.name,
      ...(this.hasSubmitters ? [quoted(row.submitter ?? '')] : []),
      ...this.settingIds.flatMap(setting => {
        const cell = row.cells[setting];
        const values = this.hasSpread
          ? [cell.meanText, cell.sdText ?? '', String(cell.rank)]
          // The unrounded rate: with 400 tasks it has two decimals (79.75).
          : [String(cell.mean), String(cell.passed ?? ''), String(cell.scored ?? ''), String(cell.rank)];
        return [...values, ...(withIntervals ? [String(cell.ci95?.[0] ?? ''), String(cell.ci95?.[1] ?? '')] : [])];
      }),
    ].join(','));
    return [header.join(','), ...lines].join('\n') + '\n';
  }
}

const RELEASE_SETS = releaseData.sets as unknown as Record<'validation' | 'test', ResultFile>;
/** The validation baselines with the submitted entries added (scripts/build_board.py). */
const VALIDATION_BOARD = validationBoard.set as unknown as ResultFile;

/** The three result sets. */
export const RESULTS: Record<ResultSet, Results> = {
  'paper-validation': new Results('paper-validation', paperData as unknown as ResultFile),
  validation: new Results('validation', VALIDATION_BOARD),
  test: new Results('test', RELEASE_SETS.test),
};

/** The result set selected on the site (the release switch, and the leaderboard's tabs within the latest release). */
export function useResults(): Results {
  return RESULTS[useResultSet()];
}

/** The task settings are the same in every result set. For the parts of the site that only name one. */
export const settingById = (id: SettingId): Setting => RESULTS['paper-validation'].settingById(id);
